import { Flags } from '@oclif/core';
import { organizationIdFlagConfig, projectIdFlagConfig, ResolvedCommand, stackFlagConfig, } from '../../baseCommands.js';
import { RUNTIME_CLI_NAME } from '../../config.js';
import { blueprintDeployCore } from '../../cores/blueprints/deploy.js';
import { Logger } from '../../utils/logger.js';
import { INSTALLER_OPTIONS } from '../../utils/types.js';
export default class DeployCommand extends ResolvedCommand {
    static needs = ['deployedStack', 'blueprint'];
    static summary = 'Deploy the local Blueprint to the remote Stack';
    static description = `Applies your local Blueprint to the remote Stack, creating, updating, or removing resources as needed. This is the primary command for applying infrastructure changes.

Before deploying, run 'blueprints plan' to preview changes. After deployment, use 'blueprints info' to verify Stack status or 'blueprints logs' to monitor activity.

Use --no-wait to queue the deployment and return immediately without waiting for completion.

Use --fn-installer to force which package manager to use when deploying functions.

Set SANITY_ASSET_TIMEOUT (seconds) to override the 180-second timeout for processing resource assets.

Set SANITY_ASSET_CONCURRENCY to override how many resource assets are processed at once (default 4).

Exit codes: 0 deployed, 2 deployment failed, 75 deployment accepted but completion could not be confirmed (rerun 'blueprints info' to check).`;
    static examples = [
        '<%= config.bin %> <%= command.id %>',
        '<%= config.bin %> <%= command.id %> --message "Enable staging dataset"',
        '<%= config.bin %> <%= command.id %> --no-wait',
        // '<%= config.bin %> <%= command.id %> --configure',
        '<%= config.bin %> <%= command.id %> --fn-installer npm',
        '<%= config.bin %> <%= command.id %> --stack <name-or-id>',
        '<%= config.bin %> <%= command.id %> --organization-id <orgId> --stack <name-or-id>',
        '<%= config.bin %> <%= command.id %> --new-stack-name <new-name>',
    ];
    static flags = {
        stack: Flags.string({ ...stackFlagConfig }),
        'project-id': Flags.string({ ...projectIdFlagConfig }),
        'organization-id': Flags.string({ ...organizationIdFlagConfig }),
        message: Flags.string({
            description: 'Message describing the deployment (e.g. reason for change)',
            char: 'm',
        }),
        'fn-installer': Flags.string({
            description: 'Which package manager to use when installing Function dependencies',
            aliases: ['function-installer', 'installer'],
            options: [...INSTALLER_OPTIONS],
            hidden: true,
        }),
        'no-wait': Flags.boolean({
            description: 'Do not wait for Stack deployment to complete',
            default: false,
        }),
        configure: Flags.boolean({
            description: 'Configure the local Blueprint interactively before deploying',
            aliases: ['config', 'init'],
            default: false,
            hidden: true,
        }),
        'new-stack-name': Flags.string({
            description: 'Set a new name for the Stack',
        }),
    };
    async preResolve() {
        if (!this.flags.configure)
            return;
        const args = ['--edit'];
        if (this.flags.path)
            args.push('--path', this.flags.path);
        if (!this.flags['validate-resources'])
            args.push('--no-validate-resources');
        if (this.flags.verbose)
            args.push('--verbose');
        await this.config.runCommand('blueprints:config', args);
    }
    async run() {
        const result = await blueprintDeployCore({
            bin: this.config.bin,
            log: Logger(this.log.bind(this), this.flags),
            auth: this.auth,
            stackId: this.stackId,
            scopeType: this.scopeType,
            scopeId: this.scopeId,
            deployedStack: this.deployedStack,
            blueprint: this.blueprint,
            cliVersion: this.config.name === RUNTIME_CLI_NAME ? undefined : this.config.version,
            validateResources: this.flags['validate-resources'],
            flags: this.flags,
        });
        if (!result.success)
            this.coreError(result);
        if (result.warnings)
            this.renderWarnings(result.warnings);
        return result.json;
    }
}
